    def test_open_blacklist_document_rejects_symlink(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "real.txt"
            target.write_text("geheim")
            link = Path(tmp) / "blacklist.txt"
            os.symlink(target, link)
