            with (
                mock.patch.object(
                    cli,
                    "_finalization_lock_owner_and_group_stably_absent",
                    return_value=True,
                ),
                mock.patch.object(
                    cli,
                    "_recorder_scope_unit_is_stably_gone",
                    return_value=True,
                ),
            ):
                acquired = cli._acquire_finalization_lock(state_file)

            self.assertIsNone(acquired)
            self.assertTrue(lock_path.exists())

