            owner = nested / "recording.wav"
            digest = hashlib.sha256(b"sensitive").hexdigest()
            orphan = owner.with_name(
                f"{cli._cleanup_backup_v3_prefix(owner, state_file)}"
                f"claim.{digest}.{'b' * 32}.bak"
            )
